import java.util.*;

class Solution {
  private final Map<Integer, Integer> tree = new HashMap<>(); // depth * 10 + position -> value

  public int pathSum(int[] nums) {
    for (int x : nums) tree.put(x / 10, x % 10);
    return walk(11, 0);
  }

  private int walk(int key, int sum) {
    Integer v = tree.get(key);
    if (v == null) return 0;
    sum += v;
    int d = key / 10, p = key % 10;
    int left = (d + 1) * 10 + 2 * p - 1, right = left + 1;
    if (!tree.containsKey(left) && !tree.containsKey(right)) return sum;
    return walk(left, sum) + walk(right, sum);
  }
}
